export function todoistProject(id = "home", extra = {}) {
  return {
    id,
    can_assign_tasks: false,
    child_order: 1,
    color: "blue",
    created_at: null,
    is_archived: false,
    is_deleted: false,
    is_favorite: false,
    is_frozen: false,
    name: id === "home" ? "Home & Admin" : id,
    updated_at: null,
    view_style: "list",
    default_order: 1,
    description: "",
    is_collapsed: false,
    is_shared: false,
    parent_id: null,
    inbox_project: false,
    ...extra,
  };
}
export function todoistTask(id = "task-1", extra = {}) {
  return {
    id,
    user_id: "owner",
    project_id: "home",
    section_id: null,
    parent_id: null,
    added_by_uid: null,
    assigned_by_uid: null,
    responsible_uid: null,
    labels: [],
    deadline: null,
    duration: null,
    checked: false,
    is_deleted: false,
    added_at: null,
    completed_at: null,
    updated_at: null,
    due: { date: "2026-10-16", is_recurring: false, string: "October 16" },
    priority: 1,
    child_order: 1,
    content: "Arrange boiler inspection",
    description: "Source: [Gmail](https://mail.google.com/mail/u/0/#all/t-boiler)",
    day_order: 1,
    is_collapsed: false,
    ...extra,
  };
}
